package com.opensocket.aievent.core.iam.authentication.event;import java.time.Instant;import java.util.Map;import java.util.Objects;public record AuthenticationSecurityEvent(String eventId,String eventType,String subjectType,String subjectId,String tenantId,String actorId,String correlationId,String reasonCode,Map<String,String> metadata,Instant occurredAt)implements AuthenticationDomainEvent{public AuthenticationSecurityEvent{if(eventId==null||eventId.isBlank())throw new IllegalArgumentException("eventId is required");if(eventType==null||eventType.isBlank())throw new IllegalArgumentException("eventType is required");subjectType=subjectType==null?"":subjectType;subjectId=subjectId==null?"":subjectId;tenantId=tenantId==null?"":tenantId;actorId=actorId==null?"":actorId;correlationId=correlationId==null?"":correlationId;reasonCode=reasonCode==null?"":reasonCode;metadata=metadata==null?Map.of():Map.copyOf(metadata);Objects.requireNonNull(occurredAt,"occurredAt");}}
